changeSet.sql:
update benutzer set systemrollen_id = sr.id
from systemrollen sr
where sr.benutzer_id = benutzer.id;

alter table if exists systemrollen drop constraint if exists fk_systemrollen_benutzer;
drop index if exists ix_systemrollen_benutzer;
alter table if exists systemrollen drop column if exists benutzer_id;
